#include <vector>
#include <string>

// Assuming User and CmdResult are defined elsewhere
// and SASLAuthenticator is a class with sendClientMessage() and isCapable() methods.

CmdResult handleUnregisteredAuthSASL(const std::vector<std::string>& parameters, User* user) {
    if (!user) {
        return CmdResult::Failure;
    }

    if (!user->isUnregistered()) {
        return CmdResult::Failure;
    }

    if (!user->hasCapability("sasl")) {
        return CmdResult::Failure;
    }

    SASLAuthenticator* authenticator = user->getSASLAuthenticator();

    if (!authenticator) {
        authenticator = new SASLAuthenticator();
        if (!authenticator) {
            return CmdResult::Failure;
        }
        user->setSASLAuthenticator(authenticator);
    }

    if (!authenticator->sendClientMessage(parameters)) {
        authenticator->announceState();
        delete authenticator;
        user->setSASLAuthenticator(nullptr);
        return CmdResult::Failure;
    }

    if (!authenticator->isComplete()) {
        delete authenticator;
        user->setSASLAuthenticator(nullptr);
        return CmdResult::Failure;
    }

    return CmdResult::Success;
}
